SELECT event_type, CASE WHEN duration_sec >= 442 THEN 'high' WHEN duration_sec >= 187 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, DATE_FORMAT(event_time, 'yyyy-MM') AS event_month, AVG(duration_sec) AS avg_duration_sec, COUNT(CASE WHEN event_type = 'page_view' THEN 1 END) AS page_view_count FROM web_events GROUP BY event_type, CASE WHEN duration_sec >= 442 THEN 'high' WHEN duration_sec >= 187 THEN 'mid' ELSE 'low' END, DATE_FORMAT(event_time, 'yyyy-MM') ORDER BY duration_sec_bucket;
